        code: 'INVALID_BODY',
        details,
      });
    }

    // Parameterized lookup — never string-concatenate the username.
    const { rows } = await pool.query(
      `SELECT id, username, password_hash, role, scope,
              jurisdiction_level, jurisdiction_id, installation_id
